SELECT al.id, al.disabled, al.approve_status AS approveStatus, al.approve_user_id AS approveUserId, al.approve_user_name AS approveUserName, al.approve_time AS approveTime, al.invalid_status AS invalidStatus, al.invalid_remark AS invalidRemark, al.code, al.description, al.address, al.detailed_address AS detailedAddress, al.remark, al.create_time AS createTime, al.create_user_name AS createUserName FROM asset_location al WHERE ${params.sqlMap.default} AND al.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
al.create_time DESC

SELECT al.id, al.disabled, al.approve_status AS approveStatus, al.approve_user_id AS approveUserId, al.approve_user_name AS approveUserName, al.approve_time AS approveTime, al.invalid_status AS invalidStatus, al.invalid_remark AS invalidRemark, al.code, al.description, al.address, al.detailed_address AS detailedAddress, al.remark, al.create_time AS createTime, al.create_user_name AS createUserName FROM asset_location al WHERE ${params.sqlMap.default}
AND al.is_deleted = false
AND al.id in
#{item}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
